SELECT gen_random_uuid()::text, 'formula', '$Z_1 = 0.8Z_L$', 'Distance Zone Reaches', '$Z_1 \approx 0.8\text{–}0.85Z_L\ (\text{instant});\quad Z_2 \approx 1.2\text{–}1.5Z_L\ (\approx 0.3\ \text{s});\quad Z_3 \approx Z_L + 1.2Z_{next}\ (\approx 1\ \text{s})$', '$\Omega$', 'Typical stepped reaches of a distance relay: fast for most of the line, delayed beyond it.', '[{"symbol":"$Z_L$","meaning":"protected line impedance","unit":"$\\Omega$"},{"symbol":"$Z_{next}$","meaning":"longest adjacent line impedance","unit":"$\\Omega$"}]'::jsonb, 'Zone 1 stops short of the far end so CT, VT and line-data errors never make it overreach.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'distance relays' AND s."active"), NULL, false, 'PENDING', now(), now()
