SELECT gen_random_uuid()::text, 'formula', '$Z(\theta) = Z_{set}\cos(\theta - \phi)$', 'Mho Relay Reach', '$Z(\theta) = Z_{set}\cos(\theta - \phi);\qquad \text{operates if } \left|Z - \tfrac12Z_{set}\angle\phi\right| < \tfrac12Z_{set}$', '$\Omega$', 'A mho relay''s reach is a circle through the origin: less reach the further the fault angle is from φ.', '[{"symbol":"$Z_{set}$","meaning":"reach at the characteristic angle","unit":"$\\Omega$"},{"symbol":"$\\phi$","meaning":"characteristic (maximum torque) angle","unit":null},{"symbol":"$\\theta$","meaning":"angle of the impedance seen","unit":null}]'::jsonb, 'Set φ near the line angle; arc resistance moves the fault off that angle and shortens the reach.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'distance relays' AND s."active"), NULL, false, 'PENDING', now(), now()
