SELECT gen_random_uuid()::text, 'formula', '$|I_1 - I_2| > k\frac{|I_1| + |I_2|}{2}$', 'Percentage Differential Characteristic', '$I_{op} = |\mathbf{I}_1 - \mathbf{I}_2| > k\,I_{rst},\qquad I_{rst} = \frac{|\mathbf{I}_1| + |\mathbf{I}_2|}{2}$', '$\text{A}$', 'A differential relay operates on the difference, restrained by the through current, so CT errors on big through faults don''t trip it.', '[{"symbol":"$\\mathbf{I}_1, \\mathbf{I}_2$","meaning":"secondary currents entering and leaving the zone","unit":"$\\text{A}$"},{"symbol":"$k$","meaning":"slope, e.g. 0.2–0.4","unit":null}]'::jsonb, 'Some relays use the larger current or the sum as restraint: check the convention.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'differential relays' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE'
