SELECT gen_random_uuid()::text, 'formula', '$\frac{\sqrt3I_Y}{N_Y} = \frac{I_\Delta}{N_\Delta}$', 'Transformer Differential CT Matching', '$\frac{\sqrt3I_Y}{N_Y} = \frac{I_\Delta}{N_\Delta}\quad (\text{CTs in delta on the wye side, in wye on the delta side})$', NULL, 'CTs connected opposite to the windings undo the 30° shift and match the currents into the relay.', '[{"symbol":"$I_Y, I_\\Delta$","meaning":"line currents on the wye and delta sides","unit":"$\\text{A}$"},{"symbol":"$N_Y, N_\\Delta$","meaning":"CT ratios on those sides","unit":null}]'::jsonb, 'The delta-connected CTs also keep zero-sequence current out, so external ground faults don''t trip it.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'transformer protection' AND s."active"), NULL, true, 'PENDING', now(), now()
