SELECT gen_random_uuid()::text, 'formula', '$I_{sc} = \frac{I_{rated}}{Z_{pu}}$', 'Transformer Through-Fault Current', '$I_{sc} = \frac{I_{rated}}{Z_{pu}}\ (\text{infinite source}),\qquad I_{sc} = \frac{I_{rated}}{Z_{pu} + Z_{s,pu}}$', '$\text{A}$', 'The largest current a transformer passes into a fault on its secondary: the basis of its protection curve.', '[{"symbol":"$I_{rated}$","meaning":"rated current on that side","unit":"$\\text{A}$"},{"symbol":"$Z_{pu}$","meaning":"transformer impedance, pu","unit":null},{"symbol":"$Z_{s,pu}$","meaning":"source impedance on the transformer base, pu","unit":null}]'::jsonb, 'A 5% transformer passes at most 20 times its rated current.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'transformer protection' AND s."active"), NULL, false, 'PENDING', now(), now()
