SELECT gen_random_uuid()::text, 'formula', '$I_2^2t = K$', 'Negative-Sequence Heating Limit', '$I_2^2t \le K\quad (I_2 \text{ in pu of rated})$', '$\text{s}$', 'Unbalance induces double-frequency rotor currents; the machine tolerates a fixed I₂²t.', '[{"symbol":"$I_2$","meaning":"negative-sequence stator current, pu","unit":null},{"symbol":"$t$","meaning":"duration","unit":"$\\text{s}$"},{"symbol":"$K$","meaning":"machine constant, about 5–30 for large turbo machines","unit":"$\\text{s}$"}]'::jsonb, 'K = 10 and I₂ = 0.5 pu allow only 40 s.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'generator protection' AND s."active"), NULL, false, 'PENDING', now(), now()
