SELECT gen_random_uuid()::text, 'formula', '$R_n = \frac{1}{3\omega C_0}$', 'Generator Neutral Resistor Sizing', '$R_n = \frac{X_{C0}}{3} = \frac{1}{3\omega C_0},\qquad R_{sec} = \frac{R_n}{N^2}$', '$\Omega$', 'High-resistance grounding: the neutral resistor equals the zero-sequence capacitive reactance, limiting transient overvoltage.', '[{"symbol":"$C_0$","meaning":"capacitance to ground per phase of everything on the generator bus","unit":"$\\text{F}$"},{"symbol":"$N$","meaning":"distribution-transformer ratio","unit":null},{"symbol":"$\\omega$","meaning":"2πf","unit":"$\\text{rad/s}$"}]'::jsonb, 'Resistor current then equals the charging current, a few amperes: the generator rides through a ground fault until tripped.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'generator protection' AND s."active"), NULL, false, 'PENDING', now(), now()
