SELECT gen_random_uuid()::text, 'formula', '$\text{coverage} = 1 - \frac{V_{set}}{V_{ph}}$', 'Stator Earth-Fault Coverage', '$V_N = xV_{ph},\qquad \text{coverage} = 1 - \frac{V_{set}}{V_{ph}}$', NULL, 'A neutral-voltage relay cannot see faults close to the neutral, where little voltage drives them.', '[{"symbol":"$x$","meaning":"fault position as a fraction of the winding from neutral","unit":null},{"symbol":"$V_{set}$","meaning":"neutral overvoltage pickup","unit":"$\\text{V}$"},{"symbol":"$V_{ph}$","meaning":"phase-to-neutral voltage","unit":"$\\text{V}$"}]'::jsonb, 'A 5% pickup covers 95% of the winding; third-harmonic schemes cover the rest.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'generator protection' AND s."active"), NULL, true, 'PENDING', now(), now()
