SELECT gen_random_uuid()::text, 'formula', '$t = \tau\ln\frac{I^2 - I_P^2}{I^2 - (kI_B)^2}$', 'Thermal Overload Trip Time', '$t = \tau\ln\frac{I^2 - I_P^2}{I^2 - (kI_B)^2}\quad (I_P = 0 \text{ from cold})$', '$\text{s}$', 'A thermal replica: time for the motor''s modelled temperature to reach trip under an overload (IEC 60255-149).', '[{"symbol":"$\\tau$","meaning":"thermal time constant","unit":"$\\text{s}$"},{"symbol":"$I$","meaning":"present current","unit":"$\\text{A}$"},{"symbol":"$I_P$","meaning":"steady current before the overload (hot state)","unit":"$\\text{A}$"},{"symbol":"$kI_B$","meaning":"current the relay allows indefinitely","unit":"$\\text{A}$"}]'::jsonb, 'A hot motor trips much sooner than a cold one at the same overload.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'motor protection' AND s."active"), NULL, false, 'PENDING', now(), now()
