SELECT gen_random_uuid()::text, 'formula', '$t = t_{LR}\left(\frac{I_{LR}}{I}\right)^2$', 'Locked-Rotor Withstand', '$I^2t = \text{const} \implies t = t_{LR}\left(\frac{I_{LR}}{I}\right)^2$', '$\text{s}$', 'How long a stalled motor survives: the rotor heats as I²t.', '[{"symbol":"$t_{LR}$","meaning":"safe stall time at locked-rotor current","unit":"$\\text{s}$"},{"symbol":"$I_{LR}$","meaning":"locked-rotor current","unit":"$\\text{A}$"},{"symbol":"$I$","meaning":"actual stall current (e.g. at reduced voltage)","unit":"$\\text{A}$"}]'::jsonb, 'At 80% voltage the stall current is 80% but the allowed time is 1.56 times longer, while starting takes longer too.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'motor protection' AND s."active"), NULL, false, 'PENDING', now(), now()
