SELECT gen_random_uuid()::text, 'formula', '$I_{eq} = \sqrt{I_1^2 + KI_2^2}$', 'Equivalent Heating Current with Unbalance', '$I_{eq} = \sqrt{I_1^2 + KI_2^2},\qquad K \approx \frac{175}{I_{LR,pu}^2} \approx 6$', NULL, 'Negative-sequence current heats the rotor several times as much as positive sequence.', '[{"symbol":"$I_1, I_2$","meaning":"positive- and negative-sequence currents, pu","unit":null},{"symbol":"$K$","meaning":"negative-sequence heating weight","unit":null}]'::jsonb, 'A few percent of voltage unbalance makes several times as much current unbalance.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'motor protection' AND s."active"), NULL, true, 'PENDING', now(), now()
