SELECT gen_random_uuid()::text, 'formula', '$V_s \ge \frac{I_f}{N}(R_{ct} + 2R_L)$', 'High-Impedance Bus Differential Setting', '$V_s \ge \frac{I_{f,\max}}{N}(R_{ct} + 2R_L),\qquad V_k \ge 2V_s$', '$\text{V}$', 'The voltage setting that keeps the relay stable when one CT fully saturates on an external fault.', '[{"symbol":"$I_{f,\\max}$","meaning":"largest external fault current","unit":"$\\text{A}$"},{"symbol":"$N$","meaning":"CT ratio","unit":null},{"symbol":"$R_{ct}, R_L$","meaning":"CT winding and one-way lead resistance","unit":"$\\Omega$"}]'::jsonb, 'All CTs must have the same ratio; the saturated CT is taken as a short circuit.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'bus and line protection' AND s."active"), NULL, false, 'PENDING', now(), now()
