SELECT gen_random_uuid()::text, 'formula', '$I_{sym} = \frac{\text{MVA}_{sc}}{\sqrt3\,\text{kV}}$', 'Breaker Interrupting Current', '$I_{sym} = \frac{\text{MVA}_{sc}}{\sqrt3\,\text{kV}},\qquad I_{asym} = I_{sym}\sqrt{1 + 2e^{-2t/\tau}},\ \tau = \frac{X}{\omega R}$', '$\text{kA}$', 'The symmetrical current a breaker must interrupt, and its RMS with the dc offset still present at contact parting.', '[{"symbol":"$\\text{MVA}_{sc}$","meaning":"short-circuit level","unit":null},{"symbol":"$t$","meaning":"contact-parting time","unit":"$\\text{s}$"},{"symbol":"$\\tau$","meaning":"dc time constant","unit":"$\\text{s}$"}]'::jsonb, 'A faster breaker or a high X/R leaves more dc offset at parting.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'circuit breaker ratings' AND s."active"), NULL, false, 'PENDING', now(), now()
