SELECT gen_random_uuid()::text, 'formula', '$I_{peak} = 2.6I_{sym}$', 'Close-and-Latch (Peak) Rating', '$I_{peak} = 2.6\,I_{sym}\ (60\ \text{Hz, X/R} = 17);\quad 2.5\,I_{sym}\ (50\ \text{Hz, IEC})$', '$\text{kA}$', 'The first-cycle peak a breaker must close onto and hold, set by the dc offset.', '[{"symbol":"$I_{sym}$","meaning":"rated symmetrical short-circuit current","unit":"$\\text{kA}$"}]'::jsonb, '√2(1 + e^(−π/(X/R))) at X/R = 17 gives 2.59, hence 2.6.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'circuit breaker ratings' AND s."active"), NULL, false, 'PENDING', now(), now()
