SELECT gen_random_uuid()::text, 'formula', '$I_g \approx \frac{V_{LN}}{R_n}$', 'Resistance-Grounded Fault Current', '$I_g \approx \frac{V_{LN}}{R_n};\qquad \text{high-resistance: } I_R \ge 3I_{C0} = 3\omega C_0V_{LN}$', '$\text{A}$', 'A neutral resistor limits ground-fault current to a set value.', '[{"symbol":"$V_{LN}$","meaning":"line-to-neutral voltage","unit":"$\\text{V}$"},{"symbol":"$R_n$","meaning":"neutral resistor","unit":"$\\Omega$"},{"symbol":"$C_0$","meaning":"capacitance to ground per phase","unit":"$\\text{F}$"}]'::jsonb, 'Low-resistance: hundreds of amperes, trip. High-resistance: a few amperes, alarm and keep running.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'system grounding' AND s."active"), NULL, false, 'PENDING', now(), now()
