SELECT gen_random_uuid()::text, 'formula', '$\frac{X_0}{X_1} \le 3,\ \frac{R_0}{X_1} \le 1$', 'Effectively Grounded System', '$\frac{X_0}{X_1} \le 3,\quad \frac{R_0}{X_1} \le 1 \implies \text{COG} \le 80\%$', NULL, 'The test for an effectively grounded system: healthy phases rise no more than 80% of line voltage on a ground fault.', '[{"symbol":"$X_0, X_1$","meaning":"zero- and positive-sequence reactances at the point","unit":"$\\Omega$"},{"symbol":"$R_0$","meaning":"zero-sequence resistance","unit":"$\\Omega$"}]'::jsonb, 'Ungrounded systems reach 100% (full line voltage) and need higher-rated arresters.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'system grounding' AND s."active"), NULL, true, 'PENDING', now(), now()
