SELECT gen_random_uuid()::text, 'formula', '$R = \frac{\rho}{2\pi L}\left(\ln\frac{4L}{a} - 1\right)$', 'Ground Rod Resistance (Dwight)', '$R = \frac{\rho}{2\pi L}\left(\ln\frac{4L}{a} - 1\right)$', '$\Omega$', 'Resistance to remote earth of one driven rod.', '[{"symbol":"$\\rho$","meaning":"soil resistivity","unit":"$\\Omega\\text{·m}$"},{"symbol":"$L$","meaning":"rod length","unit":"$\\text{m}$"},{"symbol":"$a$","meaning":"rod radius","unit":"$\\text{m}$"}]'::jsonb, 'Doubling the length nearly halves R; doubling the diameter helps little.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'system grounding' AND s."active"), NULL, false, 'PENDING', now(), now()
