SELECT gen_random_uuid()::text, 'formula', '$R_g = \frac{\rho}{4}\sqrt{\pi/A} + \frac{\rho}{L_T}$', 'Grounding Grid Resistance', '$R_g = \frac{\rho}{4}\sqrt{\frac{\pi}{A}} + \frac{\rho}{L_T}\quad (\text{Laurent–Niemann})$', '$\Omega$', 'A quick estimate of a substation grid''s resistance.', '[{"symbol":"$\\rho$","meaning":"soil resistivity","unit":"$\\Omega\\text{·m}$"},{"symbol":"$A$","meaning":"area covered by the grid","unit":"$\\text{m}^2$"},{"symbol":"$L_T$","meaning":"total length of buried conductor","unit":"$\\text{m}$"}]'::jsonb, 'Area matters most; adding conductor inside the same area helps less.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'system grounding' AND s."active"), NULL, false, 'PENDING', now(), now()
