SELECT gen_random_uuid()::text, 'formula', '$E_{touch} = (1000 + 1.5C_s\rho_s)\frac{0.116}{\sqrt{t_s}}$', 'Tolerable Step and Touch Voltage', '$E_{step} = (1000 + 6C_s\rho_s)\frac{0.116}{\sqrt{t_s}},\quad E_{touch} = (1000 + 1.5C_s\rho_s)\frac{0.116}{\sqrt{t_s}}\quad (50\ \text{kg})$', '$\text{V}$', 'The largest step and touch voltages a person can safely bear (IEEE 80).', '[{"symbol":"$\\rho_s$","meaning":"surface layer resistivity (crushed rock)","unit":"$\\Omega\\text{·m}$"},{"symbol":"$C_s$","meaning":"surface layer derating factor (1 without a layer)","unit":null},{"symbol":"$t_s$","meaning":"shock duration","unit":"$\\text{s}$"}]'::jsonb, 'For a 70 kg person use 0.157 instead of 0.116. Touch voltage is usually the limit that governs.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'system grounding' AND s."active"), NULL, false, 'PENDING', now(), now()
