SELECT gen_random_uuid()::text, 'formula', '$V_{ar} \ge \text{COG} \times V_{LL,\max}$', 'Surge Arrester Rating', '$V_{ar} \ge \text{COG} \times V_{LL,\max},\qquad \text{MCOV} \ge \frac{V_{LL,\max}}{\sqrt3}\ (\text{effectively grounded})$', '$\text{kV}$', 'An arrester must withstand the healthy-phase voltage during a ground fault elsewhere.', '[{"symbol":"$\\text{COG}$","meaning":"coefficient of grounding: ≤ 0.8 effectively grounded, 1.0 ungrounded","unit":null},{"symbol":"$V_{LL,\\max}$","meaning":"highest system line voltage","unit":"$\\text{V}$"}]'::jsonb, 'Too low a rating and it fails on temporary overvoltage; too high and it protects less.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'lightning protection' AND s."active"), NULL, false, 'PENDING', now(), now()
