SELECT gen_random_uuid()::text, 'formula', '$\text{PM} = \frac{\text{BIL}}{V_p} - 1 \ge 20\%$', 'Protective Margin', '$\text{PM} = \left(\frac{\text{BIL}}{V_p} - 1\right) \times 100\% \ge 20\%$', NULL, 'How far below the equipment''s insulation strength the arrester holds the surge.', '[{"symbol":"$\\text{BIL}$","meaning":"basic impulse insulation level of the equipment","unit":"$\\text{kV}$"},{"symbol":"$V_p$","meaning":"voltage at the equipment during the surge (arrester protective level plus lead and separation)","unit":"$\\text{kV}$"}]'::jsonb, 'At least 20% for lightning impulses (IEEE C62.22).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'lightning protection' AND s."active"), NULL, true, 'PENDING', now(), now()
