INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$E = 2.142 \times 10^6\frac{VI_{bf}t}{D^2}$', 'Arc-Flash Incident Energy (Lee)', '$E = 2.142 \times 10^6\,VI_{bf}\frac{t}{D^2}\quad (\text{J/cm}^2;\ \text{kV, kA, s, mm})$', '$\text{J/cm}^2$', 'A conservative theoretical estimate of the heat energy reaching a worker (IEEE 1584 Lee method).', '[{"symbol":"$V$","meaning":"system voltage","unit":"$\\text{kV}$"},{"symbol":"$I_{bf}$","meaning":"bolted fault current","unit":"$\\text{kA}$"},{"symbol":"$t$","meaning":"arc duration (clearing time)","unit":"$\\text{s}$"},{"symbol":"$D$","meaning":"working distance","unit":"$\\text{mm}$"}]'::jsonb, 'Energy is proportional to clearing time, so faster protection is the best mitigation. 1 cal/cm² = 4.184 J/cm². IEEE 1584-2018 advises against Lee above 15 kV.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'arc flash' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$D_B = \sqrt{2.142 \times 10^6\frac{VI_{bf}t}{E_B}}$', 'Arc-Flash Boundary (Lee)', '$D_B = \sqrt{2.142 \times 10^6\frac{VI_{bf}t}{E_B}},\qquad E_B = 5.0\ \text{J/cm}^2\ (1.2\ \text{cal/cm}^2)$', '$\text{mm}$', 'The distance at which incident energy falls to 1.2 cal/cm²: inside it, arc-rated clothing is required.', '[{"symbol":"$E_B$","meaning":"energy at the boundary, the onset of a second-degree burn","unit":"$\\text{J/cm}^2$"},{"symbol":"$V, I_{bf}, t$","meaning":"as for incident energy","unit":null}]'::jsonb, 'The boundary grows with the square root of clearing time.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE' AND s."normKey" = 'arc flash' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Protection' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
